 return (function execute() {

 var gr = new GlideRecord('x_snc_unified_hr_0_hr_case');

 // Find cases assigned to the currently logged-in HR agent
 gr.addQuery('assigned_to', gs.getUserID());
 gr.orderByDesc('sys_created_on');
 gr.query();

 var response = '';
 var count = 0;

 while (gr.next()) {

 count++;

 response += count + '. ' +
 gr.getDisplayValue('number') +
 ' - ' +
 gr.getDisplayValue('category') +
 ' - ' +
 gr.getDisplayValue('priority') +
 ' - ' +
 gr.getDisplayValue('status') +
 '\n';
 }

 if (count == 0) {
 return 'You currently have no HR cases assigned to you.';
 }

 return 'You have ' + count + ' HR case(s) assigned to you.\n\n' +
 response;

})();
})();(function() {vaInputs.final_confirm.reset();})();(function() {vaInputs.final_confirm.reset();})();ackMsg;"},{"name":"__silent_ScriptOutputPrompt_5b5e01b63cb64c389f02f385707d63b2","applicable":"(vaVars.previous_graph_node=="Always___a8faddebeabd426ca4ad95a5d7b83a7e")","direction":"Input","required":true,"prompt_msg":"vaVars.previous_graph_node="Case Attention Insights___5b5e01b63cb64c389f02f385707d63b2";vaInputs.__silent_ScriptOutputPrompt_5b5e01b63cb64c389f02f385707d63b2=true;null;","confirm_msg_on_default_value":{"msg":"","val_for_confirm":true},"nlu_text_input":false,"nlu_confirmation_prompt":false,"cardFields":[],"expert_mode":false,"acknowledge_msg":"vaVars.previous_graph_node="Case Attention Insights___5b5e01b63cb64c389f02f385707d63b2";var ackMsg=null;ackMsg=(function execute() {
 return (function execute() {

 var gr = new GlideRecord('x_snc_unified_hr_0_hr_case');

 gr.addQuery('assigned_to', gs.getUserID());
 gr.query();

 var total = 0;
 var highPriority = 0;
 var openCases = 0;
 var inProgressCases = 0;
 var attentionCases = '';

 while (gr.next()) {

 total++;

 var priority = gr.getDisplayValue('priority');
 var status = gr.getDisplayValue('status');

 if (priority == 'High'&&status!='Resolved') {
 highPriority++;
 }

 if (status == 'Open') {
 openCases++;
 }

 if (status == 'In Progress') {
 inProgressCases++;
 }

 // Cases requiring attention
 if ((priority == 'High' && status != 'Resolved') || status == 'Open') {

 attentionCases +=
 gr.getDisplayValue('number') +
 ' - ' +
 gr.getDisplayValue('priority') +
 ' - ' +
 gr.getDisplayValue('status') +
 ' - ' +
 gr.getDisplayValue('category') +
 '\n';
 }
 }

 if (total == 0) {
 return 'You currently have no cases assigned to you.';
 }

 var response = '';

 response += 'YOUR CASE WORKLOAD\n\n';

 response += 'Total Assigned: ' + total + '\n';
 response += 'High Priority: ' + highPriority + '\n';
 response += 'Open: ' + openCases + '\n';
 response += 'In Progress: ' + inProgressCases + '\n';

 if (attentionCases != '') {

 response += '\nCASES REQUIRING ATTENTION\n\n';
 response += attentionCases;

 } else {

 response += '\nNo cases currently require special attention.';
 }

